WITH remaining_keys AS (SELECT city, id FROM suppliers EXCEPT DISTINCT SELECT city, id FROM suppliers WHERE supplier_name LIKE 'T%'), reconciled AS (SELECT s.* FROM suppliers s JOIN remaining_keys k ON s.city = k.city AND s.id = k.id) SELECT CASE WHEN rating >= 3.8 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, country, MIN(rating) AS min_rating, MAX(rating) AS max_rating, COUNT(*) AS num_rows, PERCENTILE_APPROX(rating, 0.95) AS rating_p95, SORT_ARRAY(COLLECT_SET(country)) AS country_list FROM reconciled GROUP BY CASE WHEN rating >= 3.8 THEN 'HIGH' ELSE 'LOW' END, country HAVING rating_p95 > 0 ORDER BY max_rating ASC NULLS LAST
